package android.view;public class MotionEvent {public static final int ACTION_DOWN=0,ACTION_UP=1,ACTION_MOVE=2,ACTION_CANCEL=3,ACTION_OUTSIDE=4,ACTION_POINTER_DOWN=5,ACTION_POINTER_UP=6,ACTION_POINTER_INDEX_SHIFT=8,TOOL_TYPE_FINGER=1;public int action,pointerId,pointerCount=1,toolType=TOOL_TYPE_FINGER;public float x,y;public long downTime,eventTime;public final java.util.List<float[]> history=new java.util.ArrayList<>();public final java.util.List<Long> historyTimes=new java.util.ArrayList<>();public MotionEvent(int action,float x,float y,long downTime,long eventTime){this.action=action;this.x=x;this.y=y;this.downTime=downTime;this.eventTime=eventTime;}public static MotionEvent obtain(long downTime,long eventTime,int action,float x,float y,int meta){return new MotionEvent(action,x,y,downTime,eventTime);}public int getAction(){return action;}public int getActionMasked(){return action&255;}public int getActionIndex(){return action>>8;}public int getPointerId(int index){return pointerId;}public int getPointerCount(){return pointerCount;}public int getToolType(int index){return toolType;}public float getX(){return x;}public float getY(){return y;}public float getX(int index){return x;}public float getY(int index){return y;}public long getDownTime(){return downTime;}public long getEventTime(){return eventTime;}public int getHistorySize(){return history.size();}public float getHistoricalX(int pointer,int index){return history.get(index)[0];}public float getHistoricalY(int pointer,int index){return history.get(index)[1];}public long getHistoricalEventTime(int index){return historyTimes.get(index);}public void recycle(){}}
